mod compute_note_hash_and_nullifier;

use crate::{
    macros::{
        calls_generation::{
            external_functions::{generate_external_function_calls, generate_external_function_self_calls_structs},
            internal_functions::generate_call_internal_struct,
        },
        dispatch::generate_public_dispatch,
        emit_public_init_nullifier::generate_emit_public_init_nullifier,
        internals_functions_generation::{create_fn_abi_exports, process_functions},
        offchain_receive::{
            OFFCHAIN_RECEIVE_FN_NAME, OFFCHAIN_RECEIVE_PARAM_NAME, offchain_receive_param_type,
            OFFCHAIN_RECEIVE_RETURN_TYPE,
        },
        storage::STORAGE_LAYOUT_NAME,
        utils::{is_fn_contract_library_method, is_fn_external, is_fn_internal, is_fn_test, module_has_storage},
    },
    messages::discovery::{CustomMessageHandler, CustomSyncHandler},
};

use compute_note_hash_and_nullifier::generate_contract_library_methods_compute_note_hash_and_nullifier;

/// Configuration for the [`aztec`] macro.
///
/// This type lets users override different parts of the default aztec-nr contract behavior, such
/// as message handling and state synchronization. These are advanced features that require careful
/// understanding of the behavior of these systems.
///
/// ## Examples
///
/// ```noir
/// #[aztec(aztec::macros::AztecConfig::new().custom_message_handler(my_handler))]
/// contract MyContract { ... }
/// ```
pub struct AztecConfig {
    custom_message_handler: Option<CustomMessageHandler>,
    custom_sync_state: Option<CustomSyncHandler>,
}

impl AztecConfig {
    /// Creates a new `AztecConfig` with default values.
    ///
    /// Calling `new` is equivalent to invoking the [`aztec`] macro with no parameters. The different methods
    /// (e.g. [`AztecConfig::custom_message_handler`]) can then be used to change the default behavior.
    pub comptime fn new() -> Self {
        Self { custom_message_handler: Option::none(), custom_sync_state: Option::none() }
    }

    /// Sets a handler for custom messages.
    ///
    /// This enables contracts to process non-standard messages (i.e. any with a message type that is not in
    /// [`crate::messages::msg_type`]).
    ///
    /// `handler` must be a function that conforms to the
    /// [`crate::messages::discovery::CustomMessageHandler`] type signature.
    pub comptime fn custom_message_handler(&mut self, handler: CustomMessageHandler) -> Self {
        self.custom_message_handler = Option::some(handler);
        *self
    }

    /// Overrides the default state synchronization logic.
    ///
    /// The generated `sync_state` function will call `handler` instead of
    /// [`crate::messages::discovery::do_sync_state`]. The handler receives all of the same parameters, so it can
    /// run custom logic (e.g. fetching and decrypting custom logs) before, after, or instead of calling
    /// `do_sync_state`.
    ///
    /// `handler` must be a function that conforms to the
    /// [`crate::messages::discovery::CustomSyncHandler`] type signature.
    pub comptime fn custom_sync_state(&mut self, handler: CustomSyncHandler) -> Self {
        self.custom_sync_state = Option::some(handler);
        *self
    }
}

/// Enables aztec-nr features on a `contract`.
///
/// All aztec-nr contracts should have this macro invoked on them, as it is the one that processes all contract
/// functions, notes, storage, generates interfaces for external calls, and creates the message processing
/// boilerplate.
///
/// ## Examples
///
/// Most contracts can simply invoke the macro with no parameters, resulting in default aztec-nr behavior:
/// ```noir
/// #[aztec]
/// contract MyContract { ... }
/// ```
///
/// Advanced contracts can use [`AztecConfig`] to customize parts of its behavior, such as message
/// processing.
/// ```noir
/// #[aztec(aztec::macros::AztecConfig::new().custom_message_handler(my_handler))]
/// contract MyAdvancedContract { ... }
/// ```
#[varargs]
pub comptime fn aztec(m: Module, args: [AztecConfig]) -> Quoted {
    let num_args = args.len();
    let config = if num_args == 0 {
        AztecConfig::new()
    } else if num_args == 1 {
        args[0]
    } else {
        panic(f"#[aztec] expects 0 or 1 arguments, got {num_args}")
    };

    // Functions that don't have #[external(...)], #[contract_library_method], or #[test] are not allowed in contracts.
    check_each_fn_macroified(m);

    // We generate new functions prefixed with `__aztec_nr_internals__` and we replace the original functions' bodies
    // with `static_assert(false, ...)` to prevent them from being called directly from within the contract.
    let functions = process_functions(m);

    // We generate structs and their implementations necessary for convenient functions calls.
    let interface = generate_contract_interface(m);
    let self_call_structs = generate_external_function_self_calls_structs(m);
    let call_internal_struct = generate_call_internal_struct(m);

    // We generate ABI exports for all the external functions in the contract.
    let fn_abi_exports = create_fn_abi_exports(m);

    // We generate `_compute_note_hash`, `_compute_note_nullifier` (and the deprecated
    // `_compute_note_hash_and_nullifier` wrapper) only if they are not already implemented.
    // If they are implemented we just insert empty quotes.
    let contract_library_method_compute_note_hash_and_nullifier = if !m.functions().any(|f| {
        // Note that we don't test for `_compute_note_hash` or `_compute_note_nullifier` in order to make this simpler
        // - users must either implement all three or none.
        // Down the line we'll remove this check and use `AztecConfig`.
        f.name() == quote { _compute_note_hash_and_nullifier }
    }) {
        generate_contract_library_methods_compute_note_hash_and_nullifier()
    } else {
        quote {}
    };
    let process_custom_message_option = if config.custom_message_handler.is_some() {
        let handler = config.custom_message_handler.unwrap();
        quote { Option::some($handler) }
    } else {
        quote { Option::<aztec::messages::discovery::CustomMessageHandler>::none() }
    };

    let offchain_inbox_sync_option = quote {
        Option::some(aztec::messages::processing::offchain::sync_inbox)
    };

    if m.functions().any(|f| f.name() == quote { sync_state }) {
        panic(
            "User-defined 'sync_state' is not allowed. Use AztecConfig::custom_sync_state() to customize sync behavior.",
        );
    }

    let custom_sync_handler = if config.custom_sync_state.is_some() {
        let handler = config.custom_sync_state.unwrap();
        Option::some(quote { $handler })
    } else {
        Option::none()
    };

    let sync_state_fn_and_abi_export = generate_sync_state(
        process_custom_message_option,
        offchain_inbox_sync_option,
        custom_sync_handler,
    );

    if m.functions().any(|f| f.name() == quote { offchain_receive }) {
        panic(
            "User-defined 'offchain_receive' is not allowed. The function is auto-injected by the #[aztec] macro. See https://docs.aztec.network/errors/7",
        );
    }
    let offchain_receive_fn_and_abi_export = generate_offchain_receive();

    let (has_public_init_nullifier_fn, emit_public_init_nullifier_fn_body) = generate_emit_public_init_nullifier(m);
    let public_dispatch = generate_public_dispatch(m, has_public_init_nullifier_fn);

    quote {
        $interface
        $self_call_structs
        $call_internal_struct
        $functions
        $fn_abi_exports
        $contract_library_method_compute_note_hash_and_nullifier
        $public_dispatch
        $sync_state_fn_and_abi_export
        $emit_public_init_nullifier_fn_body
        $offchain_receive_fn_and_abi_export
    }
}

comptime fn generate_contract_interface(m: Module) -> Quoted {
    let calls = generate_external_function_calls(m);

    let module_name = m.name();

    let has_storage_layout = module_has_storage(m) & STORAGE_LAYOUT_NAME.get(m).is_some();
    let storage_layout_getter = if has_storage_layout {
        let storage_layout_name = STORAGE_LAYOUT_NAME.get(m).unwrap();
        quote {
            pub fn storage_layout() -> StorageLayoutFields {
                $storage_layout_name.fields
            }
        }
    } else {
        quote {}
    };

    let library_storage_layout_getter = if has_storage_layout {
        quote {
            #[contract_library_method]
            $storage_layout_getter
        }
    } else {
        quote {}
    };

    quote {
        pub struct $module_name {
            pub target_contract: aztec::protocol::address::AztecAddress
        }

        impl $module_name {
            $calls

            pub fn at(
                addr: aztec::protocol::address::AztecAddress
            ) -> Self {
                Self { target_contract: addr }
            }

            pub fn interface() -> Self {
                Self { target_contract: aztec::protocol::address::AztecAddress::zero() }
            }

            $storage_layout_getter
        }

        #[contract_library_method]
        pub fn at(
            addr: aztec::protocol::address::AztecAddress
        ) -> $module_name {
            $module_name { target_contract: addr }
        }

        #[contract_library_method]
        pub fn interface() -> $module_name {
            $module_name { target_contract: aztec::protocol::address::AztecAddress::zero() }
        }

        $library_storage_layout_getter

    }
}

/// Generates the `sync_state` utility function that performs message discovery.
comptime fn generate_sync_state(
    process_custom_message_option: Quoted,
    offchain_inbox_sync_option: Quoted,
    custom_sync_handler: Option<Quoted>,
) -> Quoted {
    let body = if custom_sync_handler.is_some() {
        let handler = custom_sync_handler.unwrap();
        quote {
            $handler(
                address,
                _compute_note_hash,
                _compute_note_nullifier,
                $process_custom_message_option,
                $offchain_inbox_sync_option,
                scope,
            );
        }
    } else {
        quote {
            aztec::messages::discovery::do_sync_state(
                address,
                _compute_note_hash,
                _compute_note_nullifier,
                $process_custom_message_option,
                $offchain_inbox_sync_option,
                scope,
            );
        }
    };

    quote {
        pub struct sync_state_parameters {
            pub scope: aztec::protocol::address::AztecAddress,
        }

        #[abi(functions)]
        pub struct sync_state_abi {
            parameters: sync_state_parameters,
        }

        #[aztec::macros::internals_functions_generation::abi_attributes::abi_utility]
        unconstrained fn sync_state(scope: aztec::protocol::address::AztecAddress) {
            let address = aztec::context::UtilityContext::new().this_address();
            $body
        }
    }
}

/// Generates an `offchain_receive` utility function that lets callers add messages to the offchain message inbox.
///
/// For more details, see `aztec::messages::processing::offchain::receive`.
comptime fn generate_offchain_receive() -> Quoted {
    let param_type = offchain_receive_param_type(quote { aztec });
    let parameters_struct_name = f"{OFFCHAIN_RECEIVE_FN_NAME}_parameters".quoted_contents();
    let abi_struct_name = f"{OFFCHAIN_RECEIVE_FN_NAME}_abi".quoted_contents();

    quote {
        pub struct $parameters_struct_name {
            pub $OFFCHAIN_RECEIVE_PARAM_NAME: $param_type,
        }

        #[abi(functions)]
        pub struct $abi_struct_name {
            parameters: $parameters_struct_name,
        }

        /// Receives offchain messages into this contract's offchain inbox for subsequent processing.
        ///
        /// Each message is routed to the inbox scoped to its `recipient` field.
        ///
        /// For more details, see `aztec::messages::processing::offchain::receive`.
        ///
        /// This function is automatically injected by the `#[aztec]` macro.
        #[aztec::macros::internals_functions_generation::abi_attributes::abi_utility]
        unconstrained fn $OFFCHAIN_RECEIVE_FN_NAME($OFFCHAIN_RECEIVE_PARAM_NAME: $param_type) -> $OFFCHAIN_RECEIVE_RETURN_TYPE {
            let address = aztec::context::UtilityContext::new().this_address();
            aztec::messages::processing::offchain::receive(address, $OFFCHAIN_RECEIVE_PARAM_NAME);
        }
    }
}

/// Checks that all functions in the module have a context macro applied.
///
/// Non-macroified functions are not allowed in contracts. They must all be one of
/// [`crate::macros::functions::external`], [`crate::macros::functions::internal`] or `test`.
comptime fn check_each_fn_macroified(m: Module) {
    for f in m.functions() {
        let name = f.name();
        if !is_fn_external(f) & !is_fn_contract_library_method(f) & !is_fn_internal(f) & !is_fn_test(f) {
            // We  don't suggest that #[contract_library_method] is allowed because we don't want to introduce another
            // concept
            panic(
                f"Function {name} must be marked as either #[external(...)], #[internal(...)], or #[test]",
            );
        }
    }
}

122.source:
//! Stubs are auto-generated wrapper functions that provide an ergonomic interface for cross-contract calls. ! Instead
// of manually serializing arguments and creating call interfaces, stubs allow natural syntax, e.g. for ! enqueuing
// calls to public functions: ! !   ExternalContract.at(address).some_method(arg1, arg2).enqueue()

use crate::macros::utils::compute_fn_selector;
use crate::protocol::meta::utils::derive_serialization_quotes;
use std::meta::unquote;

comptime global FROM_FIELD: TypedExpr = {
    let from_field_trait = quote { crate::protocol::traits::FromField }.as_trait_constraint();
    let function_selector_typ = quote { crate::protocol::abis::function_selector::FunctionSelector }.as_type();
    function_selector_typ.get_trait_impl(from_field_trait).unwrap().methods().filter(|m| {
        m.name() == quote { from_field }
    })[0]
        .as_typed_expr()
};

/// Utility function creating stubs used by all the stub functions in this file.
comptime fn create_stub_base(f: FunctionDefinition) -> (Quoted, Quoted, Quoted, Quoted, u32, Quoted, u32, Field) {
    // Dear privacy adventurer, chances are, you've command+clicked on the name of an external function call -- seeking
    // to view that function -- only to end up here. Here's an explanation: The external contract that you're calling
    // was likely annotated with the `#[aztec]` annotation -- as all good aztec contracts are. This triggers a macro
    // which generates a "contract interface" for that contract, which is effectively a pretty interface that gives
    // natural contract calling semantics:
    //
    // `MyImportedContract.at(some_address).my_method(arg1, arg2).enqueue();
    //
    // Unfortunately, the usage of macros makes it a bit of a black box. To actually view the target function, you
    // could instead command+click on `MyImportedContract`, or you can just manually search it. If you want to view the
    // noir code that gets generated by this macro, you can use `nargo expand` on your contract.
    create_stub_base_from_parts(f.name(), f.parameters())
}

/// Variant of `create_stub_base` that takes raw `(name, parameters)` instead of a `FunctionDefinition`.
///
/// This lets macro-injected functions (e.g. `offchain_receive`) reuse the stub-generation machinery without needing a
/// `FunctionDefinition`.
pub(crate) comptime fn create_stub_base_from_parts(
    fn_name: Quoted,
    fn_parameters: [(Quoted, Type)],
) -> (Quoted, Quoted, Quoted, Quoted, u32, Quoted, u32, Field) {
    let fn_parameters_list = fn_parameters.map(|(name, typ): (Quoted, Type)| quote { $name: $typ }).join(quote {,});

    let (serialized_args_array_construction, serialized_args_array_len_quote, serialized_args_array_name) =
        derive_serialization_quotes(fn_parameters, false);
    let serialized_args_array_len: u32 = unquote!(quote { ($serialized_args_array_len_quote) as u32 });

    let fn_name_str = f"\"{fn_name}\"".quoted_contents();
    let fn_name_len: u32 = unquote!(quote { $fn_name_str.as_bytes().len() });
    let fn_selector: Field = compute_fn_selector(fn_name, fn_parameters);

    (
        fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name,
        serialized_args_array_len, fn_name_str, fn_name_len, fn_selector,
    )
}

pub(crate) comptime fn create_private_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, serialized_args_array_len, fn_name_str, fn_name_len, fn_selector) =
        create_stub_base(f);
    let fn_return_type = f.return_type();

    quote {
        pub fn $fn_name(self, $fn_parameters_list) -> aztec::context::calls::PrivateCall<$fn_name_len, $serialized_args_array_len, $fn_return_type> {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            aztec::context::calls::PrivateCall::new(
                self.target_contract,
                selector,
                $fn_name_str,
                $serialized_args_array_name,
            )
        }
    }
}

pub(crate) comptime fn create_private_static_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, serialized_args_array_len, fn_name_str, fn_name_len, fn_selector) =
        create_stub_base(f);
    let fn_return_type = f.return_type();

    quote {
        pub fn $fn_name(self, $fn_parameters_list) -> aztec::context::calls::PrivateStaticCall<$fn_name_len, $serialized_args_array_len, $fn_return_type> {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            aztec::context::calls::PrivateStaticCall::new(
                self.target_contract,
                selector,
                $fn_name_str,
                $serialized_args_array_name,
            )
        }
    }
}

pub(crate) comptime fn create_public_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, serialized_args_array_len, fn_name_str, fn_name_len, fn_selector) =
        create_stub_base(f);
    let fn_return_type = f.return_type();

    quote {
        pub fn $fn_name(self, $fn_parameters_list) -> aztec::context::calls::PublicCall<$fn_name_len, $serialized_args_array_len, $fn_return_type> {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            aztec::context::calls::PublicCall::new(
                self.target_contract,
                selector,
                $fn_name_str,
                $serialized_args_array_name,
            )
        }
    }
}

pub(crate) comptime fn create_public_static_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, serialized_args_array_len, fn_name_str, fn_name_len, fn_selector) =
        create_stub_base(f);
    let fn_return_type = f.return_type();

    quote {
        pub fn $fn_name(self, $fn_parameters_list) -> aztec::context::calls::PublicStaticCall<$fn_name_len, $serialized_args_array_len, $fn_return_type> {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            aztec::context::calls::PublicStaticCall::new(
                self.target_contract,
                selector,
                $fn_name_str,
                $serialized_args_array_name,
            )
        }
    }
}

pub(crate) comptime fn create_utility_stub(f: FunctionDefinition) -> Quoted {
    create_utility_stub_from_parts(f.name(), f.parameters(), f.return_type())
}

/// Variant of `create_utility_stub` that takes raw `(name, parameters, return_type)` instead of `FunctionDefinition`.
pub(crate) comptime fn create_utility_stub_from_parts(
    fn_name: Quoted,
    fn_parameters: [(Quoted, Type)],
    fn_return_type: Type,
) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, serialized_args_array_len, fn_name_str, fn_name_len, fn_selector) =
        create_stub_base_from_parts(fn_name, fn_parameters);

    quote {
        pub fn $fn_name(self, $fn_parameters_list) -> aztec::context::calls::UtilityCall<$fn_name_len, $serialized_args_array_len, $fn_return_type> {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            aztec::context::calls::UtilityCall::new(
                self.target_contract,
                selector,
                $fn_name_str,
                $serialized_args_array_name,
            )
        }
    }
}

// Self-call stub generation functions for CallSelf, CallSelfStatic, EnqueueSelf, and EnqueueSelfStatic structs. Unlike
// the stubs above, the self-call stubs directly perform the call instead of returning a struct that can be later used
// to perform the call.

/// Creates a stub for calling a private function (or static private function if `is_static` is true) from private
/// context (for CallSelf<&mut PrivateContext> and CallSelfStatic<&mut PrivateContext>).
pub comptime fn create_private_self_call_stub(f: FunctionDefinition, is_static: bool) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, _, _, _, fn_selector) =
        create_stub_base(f);
    let fn_return_type = f.return_type();

    quote {
        pub fn $fn_name(self, $fn_parameters_list) -> $fn_return_type {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            let args_hash = aztec::hash::hash_args($serialized_args_array_name);
            aztec::oracle::execution_cache::store($serialized_args_array_name, args_hash);
            let returns_hash = self.context.call_private_function_with_args_hash(
                self.address,
                selector,
                args_hash,
                $is_static
            );
            returns_hash.get_preimage()
        }
    }
}

/// Creates a stub for calling a public function from public context (for CallSelf<PublicContext>)
pub comptime fn create_public_self_call_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, _, fn_name_str, _, fn_selector) =
        create_stub_base(f);
    let fn_return_type = f.return_type();

    // TODO: It makes sense to drop the use of PublicStaticCall struct here and just perform the call directly but
    // before doing that we need to drop the use of slices from return values because we cannot return slices from an
    // unconstrained function. This is not a priority right now.
    quote {
        pub fn $fn_name(self, $fn_parameters_list) -> $fn_return_type {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            unsafe {
                aztec::context::calls::PublicCall::new(
                    self.address,
                    selector,
                    $fn_name_str,
                    $serialized_args_array_name,
                ).call(self.context)
            }
        }
    }
}

/// Creates a static stub for calling a public view function from public context (for CallSelfStatic<PublicContext>)
pub comptime fn create_public_self_call_static_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, _, fn_name_str, _, fn_selector) =
        create_stub_base(f);
    let fn_return_type = f.return_type();

    // TODO: It makes sense to drop the use of PublicStaticCall struct here and just perform the call directly but
    // before doing that we need to drop the use of slices from return values because we cannot return slices from an
    // unconstrained function. This is not a priority right now.
    quote {
        pub fn $fn_name(self, $fn_parameters_list) -> $fn_return_type {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            unsafe {
                aztec::context::calls::PublicStaticCall::new(
                    self.address,
                    selector,
                    $fn_name_str,
                    $serialized_args_array_name,
                ).view(self.context)
            }
        }
    }
}

/// Creates a static stub for enqueuing a public view function from private context (for EnqueueSelfStatic<&mut
/// PrivateContext>)
pub comptime fn create_public_self_enqueue_static_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, _serialized_args_array_len, _fn_name_str, _fn_name_len, fn_selector) =
        create_stub_base(f);

    quote {
        pub fn $fn_name(self, $fn_parameters_list) {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            let calldata = [aztec::protocol::traits::ToField::to_field(selector)].concat($serialized_args_array_name);
            let calldata_hash = aztec::hash::hash_calldata_array(calldata);
            aztec::oracle::execution_cache::store(calldata, calldata_hash);
            self.context.call_public_function_with_calldata_hash(
                self.address,
                calldata_hash,
                /*is_static_call=*/ true,
                /*hide_msg_sender=*/ false,
            );
        }
    }
}

/// Creates a stub for calling a utility function on the same contract (for CallSelfUtility).
pub comptime fn create_utility_self_call_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, _, _, _, fn_selector) =
        create_stub_base(f);
    let fn_return_type = f.return_type();

    quote {
        pub unconstrained fn $fn_name(self, $fn_parameters_list) -> $fn_return_type {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            let returns = aztec::oracle::call_utility_function::call_utility_function(
                self.address, selector, $serialized_args_array_name,
            );
            aztec::protocol::traits::Deserialize::deserialize(returns)
        }
    }
}

/// Creates a stub for enqueuing a public function from private context (for EnqueueSelf<&mut PrivateContext>)
pub comptime fn create_public_self_enqueue_stub(f: FunctionDefinition) -> Quoted {
    let (fn_name, fn_parameters_list, serialized_args_array_construction, serialized_args_array_name, _serialized_args_array_len, _fn_name_str, _fn_name_len, fn_selector) =
        create_stub_base(f);

    quote {
        pub fn $fn_name(self, $fn_parameters_list) {
            $serialized_args_array_construction
            let selector = $FROM_FIELD($fn_selector);
            let calldata = [aztec::protocol::traits::ToField::to_field(selector)].concat($serialized_args_array_name);
            let calldata_hash = aztec::hash::hash_calldata_array(calldata);
            aztec::oracle::execution_cache::store(calldata, calldata_hash);
            self.context.call_public_function_with_calldata_hash(
                self.address,
                calldata_hash,
                /*is_static_call=*/ false,
                /*hide_msg_sender=*/ false,
            );
        }
    }
}

