        let vector2 = [3, 4, 5].as_vector();
        let result = vector1.append(vector2);
        assert_eq(result, [1, 2, 3, 4, 5].as_vector());
    }

    #[test]
    fn as_array_single() {
        let vector = [42].as_vector();
        let array: [Field; 1] = vector.as_array();
        assert_eq(array[0], 42);
